class DetectSquares {
    map<pair<int,int>,int>freq;
public:
    DetectSquares(){}
    void add(vector<int> point){++freq[{point[0],point[1]}];}
    int count(vector<int> point){int x=point[0],y=point[1],ans=0;
        for(auto &entry:freq){int xx=entry.first.first,yy=entry.first.second;
            if(xx!=x||yy==y)continue;
            int d=abs(yy-y);
            ans+=entry.second*freq[{x+d,y}]*freq[{x+d,yy}];
            ans+=entry.second*freq[{x-d,y}]*freq[{x-d,yy}];
        }
        return ans;
    }
};
